with okko as materialized (select g.id gid, g.nom, (select jsonb_object_agg(n->>'id', true) from jsonb_array_elements(s.doc->'noeuds') n where n->>'type' = 'donnees' and n->>'bareme' in (select br->>'id' from jsonb_array_elements(s.doc->'baremes') br where br->>'prereglage' = 'binaire')) ids from b.grille g join b.structure s on s.id = g.structure_id) select o.nom grille, d.participant_id, t.k noeud, (t.e->>'v')::int valeur from okko o join b.dossier d on d.grille_id = o.gid cross join lateral jsonb_each(d.doc->'notes') t(k, e) where o.ids ? t.k and t.e->'v' <> 'null';
